<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\Tenant\Domain\TenantRef;
use Civi\Lughauth\Features\Document\Theme\Domain\ThemeRef;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateCodeVO;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateTenantVO;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateThemeVO;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateChannelVO;
use Civi\Lughauth\Features\Document\Template\Domain\TemplateChannelOptions;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateEnabledVO;
use Civi\Lughauth\Features\Document\Template\Domain\ValueObject\TemplateVersionVO;
use Civi\Lughauth\Features\Document\Template\Application\Usecase\Enable\TemplateEnableResult;
use PHPUnit\Framework\TestCase;

final class TemplateEnableResultUnitTest extends TestCase
{
    public function test(): void
    {
        $value = new TemplateEnableResult();
        $codeOneValue = 'one';
        $codeOtherValue = 'other';
        $copy = $value->code($codeOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals('one', $value->getCode());
        $this->assertNotEquals('other', $value->getCode());
        $this->assertEquals('one', $value->getCodeOrCurrent(TemplateCodeVO::from($codeOtherValue))->value());
        $this->assertNotEquals('other', $value->getCodeOrCurrent(TemplateCodeVO::from($codeOtherValue))->value());
        $value->unsetCode();
        $this->assertEquals('other', $value->getCodeOrCurrent(TemplateCodeVO::from($codeOtherValue))->value());
        $this->assertNotEquals('one', $value->getCodeOrCurrent(TemplateCodeVO::from($codeOtherValue))->value());
        $tenantOneValue = new TenantRef('one');
        $tenantOtherValue = new TenantRef('other');
        $copy = $value->tenant($tenantOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new TenantRef('one'), $value->getTenant());
        $this->assertNotEquals(new TenantRef('other'), $value->getTenant());
        $this->assertEquals(new TenantRef('one'), $value->getTenantOrCurrent(TemplateTenantVO::from($tenantOtherValue))->value());
        $this->assertNotEquals(new TenantRef('other'), $value->getTenantOrCurrent(TemplateTenantVO::from($tenantOtherValue))->value());
        $value->unsetTenant();
        $this->assertEquals(new TenantRef('other'), $value->getTenantOrCurrent(TemplateTenantVO::from($tenantOtherValue))->value());
        $this->assertNotEquals(new TenantRef('one'), $value->getTenantOrCurrent(TemplateTenantVO::from($tenantOtherValue))->value());
        $themeOneValue = new ThemeRef('one');
        $themeOtherValue = new ThemeRef('other');
        $copy = $value->theme($themeOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(new ThemeRef('one'), $value->getTheme());
        $this->assertNotEquals(new ThemeRef('other'), $value->getTheme());
        $this->assertEquals(new ThemeRef('one'), $value->getThemeOrCurrent(TemplateThemeVO::from($themeOtherValue))->value());
        $this->assertNotEquals(new ThemeRef('other'), $value->getThemeOrCurrent(TemplateThemeVO::from($themeOtherValue))->value());
        $value->unsetTheme();
        $this->assertEquals(new ThemeRef('other'), $value->getThemeOrCurrent(TemplateThemeVO::from($themeOtherValue))->value());
        $this->assertNotEquals(new ThemeRef('one'), $value->getThemeOrCurrent(TemplateThemeVO::from($themeOtherValue))->value());
        $channelOneValue = TemplateChannelOptions::MAIL;
        $channelOtherValue = TemplateChannelOptions::SMS;
        $copy = $value->channel($channelOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(TemplateChannelOptions::MAIL, $value->getChannel());
        $this->assertNotEquals(TemplateChannelOptions::SMS, $value->getChannel());
        $this->assertEquals(TemplateChannelOptions::MAIL, $value->getChannelOrCurrent(TemplateChannelVO::from($channelOtherValue))->value());
        $this->assertNotEquals(TemplateChannelOptions::SMS, $value->getChannelOrCurrent(TemplateChannelVO::from($channelOtherValue))->value());
        $value->unsetChannel();
        $this->assertEquals(TemplateChannelOptions::SMS, $value->getChannelOrCurrent(TemplateChannelVO::from($channelOtherValue))->value());
        $this->assertNotEquals(TemplateChannelOptions::MAIL, $value->getChannelOrCurrent(TemplateChannelVO::from($channelOtherValue))->value());
        $enabledOneValue = true;
        $enabledOtherValue = false;
        $copy = $value->enabled($enabledOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(true, $value->isEnabled());
        $this->assertNotEquals(false, $value->isEnabled());
        $this->assertEquals(true, $value->getEnabledOrCurrent(TemplateEnabledVO::from($enabledOtherValue))->value());
        $this->assertNotEquals(false, $value->getEnabledOrCurrent(TemplateEnabledVO::from($enabledOtherValue))->value());
        $value->unsetEnabled();
        $this->assertEquals(false, $value->getEnabledOrCurrent(TemplateEnabledVO::from($enabledOtherValue))->value());
        $this->assertNotEquals(true, $value->getEnabledOrCurrent(TemplateEnabledVO::from($enabledOtherValue))->value());
        $versionOneValue = 1;
        $versionOtherValue = 2;
        $copy = $value->version($versionOneValue);
        $this->assertSame($value, $copy);
        $this->assertEquals(1, $value->getVersion());
        $this->assertNotEquals(2, $value->getVersion());
        $this->assertEquals(1, $value->getVersionOrCurrent(TemplateVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(2, $value->getVersionOrCurrent(TemplateVersionVO::from($versionOtherValue))->value());
        $value->unsetVersion();
        $this->assertEquals(2, $value->getVersionOrCurrent(TemplateVersionVO::from($versionOtherValue))->value());
        $this->assertNotEquals(1, $value->getVersionOrCurrent(TemplateVersionVO::from($versionOtherValue))->value());
        $this->assertSame($value, $copy);
    }
}
